import { query } from "convex:/_system/repl/wrappers.js";
export default query({
  handler: async (ctx) => {
    const rows = await ctx.db.query("jevJudgments").order("desc").take(20);
    return rows.map((r) => ({
      _id: r._id,
      ideaId: r.ideaId,
      status: r.status,
      verdict: r.verdict,
      error: r.error ?? null,
    }));
  },
});
